from typing import List
from bisect import bisect_right

def max_abs_diff(i: List[int], k: int, n: int) -> int:
    stack = []
    for j in range(k, n):
        while stack and j > k and (j - stack[-1][1]) > (i[j] - i[stack[-1][1]]):
            stack.pop()
        if stack:
            yield i[stack[-1][1]], i[j]
        stack.append((i[j], j))
    while stack:
        yield i[stack[-1][1]], i[-1]
        stack.pop()

def max_diff(arr: List[int], k: int) -> int:
    max_diff = 0
    for start, end in max_abs_diff(arr, k, len(arr)):
        diff = bisect_right(arr, end) - bisect_right(arr, start)
        max_diff = max(max_diff, diff)
    return max_diff

# Example usage
