from itertools import accumulate
from bisect

def minimize_chips(chips, a):
    sorted_chips = sorted(chips)
    min_moves = []
    for c in sorted_chips:
        moves = c // a
        if moves - accumulate(minimize_chips(chips[:c], a)[:moves])[-1] > 0:
            min_moves.append(moves)
        else:
            min_moves.append(moves-1)
    return min_moves

def find_min_moves(target, a, b):
    a_allocated = b_allocated = 0
    min_moves = accumulate(minimize_chips(target, a), initial=0)
    while (b+1):
        for i in range(a):
            a_allocated += a
            b_allocated += b
            if min_moves[i] - (a_allocated - b_allocated) <= b:
                return a_allocated
    return min_moves[-1] - (a_allocated - b_allocated)

def play_game_chips(target, a, b, turns):
    a_allocated = b_allocated = 0
    if maximize_chips(target, a):
        return []  # Alice wins regardless of who starts
    equal_chips = []
    for a in sorted(maximize_chips(target, a)):
        for b in sorted(maximize_chips(target, b)):
            if find_min_moves(target, a, b) <= max(minimize_chips(target, a), minimize_chips(target, b), len(maximize_chips(target, a))) // max(len(maximize_chips(target, a)), len(maximize_chips(target, b))):
                equal_chips.append((target, a, b))
    result = {
        'a_wins': a-1 >= b,
        'b_wins': b-1 >= a,
        'first_player': True,
        'second_player': False,
    }
    for t, a, b in equal_chips:
        min_moves = [a_allocated, b_allocated]
        # Determine who starts
        first = (a > b) or (a - b <= a)
        if (len(maximize_chips(t, a)) + first) // 2 > len(maximize_chips(t, b)) // 2:
            first <<= 1
        first >>= 1
        if first:
            if maximize_chips(t, b):
                first = True
            min_moves[~~min_moves[0]] += a - b
            result['a_wins'] |= min_moves[0] >= b
            result['b_wins'] |= min_moves[1] >= a
    return result

def maximize_chips(chips, limit):
    return set((i, j) for i in accumulate(maximize_chips(chips[:i], limit)) for j in accumulate(maximize_chips(chips[:i], limit)))

