import sys

def get_neighbors(id, graph):
    return graph.get(id, [])

def find_reverse_path(source, target, paths, visited):
    if source == target:
        return True

    visited.add(source)
    for neighbor in get_neighbors(source, graph):
        if neighbor not in visited and find_reverse_path(neighbor, target, paths, visited):
            paths.add((source, neighbor))
            return True

    visited.remove(source)
    return False

def find_permutation(k):
    all_permutations = []
    for i in range(1, k + 1):
        all_permutations += [
            i for i in range(1, k + 1) if find_reverse_path(i, 1, set(), set())][::-1]
    return all_permutations[:k]

def solve_queries():
    n, m = map(int, sys.stdin.readline().split())
    graph = {i: set() for i in range(1, n + 1)}

    for _ in range(m):
        query = sys.stdin.readline().strip()
        if query.startswith("+"):
            u, v, c = map(int, query[2:].split())
            graph[u].add((v, c))
            graph[v].add((u, c))
        elif query.startswith("-"):
            u, v = map(int, query[2:].split())
            graph[u].discard((v, query[0]))
            graph[v].discard((u, query[0]))
        elif query.startswith("?"):
