                            path1.append(neighbor)
                for neighbor, label in graph[perm[-1]]:
                    if label == perm[0]:
                        path2.append(neighbor)

                if any(label in graph[neighbor] for label, neighbor in path1[1:]) and all(label in graph[neighbor] for label, neighbor in zip(path2, reversed(path1))):
                    reverse_perm = [perm[j] for j in range(len(perm)) if graph[perm[j]][-1][1] == perm[(perm.index(perm[j]) + len(perm)) % len(perm)]][::-1]

