from collections import defaultdict

def can_place_tiles(n, k, edges):
    org_adjacent = defaultdict(list)

    for e in edges:
        u, v = e
        org_adjacent[u-1].append(v-1)
        org_adjacent[v-1].append(u-1)

    used = [False] * n

    queue = [0]
    visited = set(range(n))

    while queue:
        node = queue.pop(0)
        if not used[node]:
            used[node] = True
            for neighbor in org_adjacent[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    if len(visited) != n:
        return "No"

    three, four = visited.count(3), visited.count(4)

    if k in (3, 4) and three == 1 and four == 0:
        return "Yes\n" + "1" * n
    elif k in (3, 4) and three == 0 and four != 1:
        return "No"
    elif k == 3 and three != 1:
        return "No"
    elif k == 4 and k != 3:
        return "No"

    return "Yes\n" + "1" * n

