from collections import defaultdict

def parse_cnf(cnf_input):
    clauses = []
    for line in cnf_input:
        k, literals = line.split()
        k = int(k)
        clauses.append([int(l) for l in literals.split()])
    return clauses

def verify_satisfiability(clauses):
    visited = set()
    assignment = defaultdict(lambda: 0)
    for clause in clauses:
        mineible = set()
        for literal in clause:
            if literal not in visited:
                mineible.add((literal, assignment[literal]))
                visited.add(literal)
        for literal, true in mineible:
            if true:
                assignment[literal] += 1
            else:
                assignment[literal] -= 1
        # In the middle of a clause, assignment[literal] is the count of literals which are already true. 
        # If there are more true literals than there are clauses left, then CNF 'Fails'.
        if len(clause) - assignment[literal] > 0:
            return False
    return True

def get_satisfying_assignment(clauses):
    total_true = sum([len(clauses[0N]), len(clauses[1N]), ...]) - len(clauses)
    if total_true != len(clauses):
        return 'NO', ''
    else:
        return 'YES', ' '.join(map(str, [assignment[lit] for lit, _ in clauses]))

def main():
    n, m = map(int, input().split())
    cnf_input = [input().split() for _ in range(n)]
    clauses = parse_cnf(cnf_input)
    result, assignment = get_satisfying_assignment(clauses)
    print(result)
    print(assignment)

if __name__ == "__main__":
    main()
