import heapq

def min_max_tallest_bamboo(n, m, k, p):
    heights_and_grow_rates = []
    max_heights = []
    for h, a in zip([0] + [int(h) for h in input().split()], [0] + [int(a) for a in input().split()]):
        heapq.heappush(heights_and_grow_rates, (h, h + 1))
        if h + 1 > 0:
            max_heights.append(h)

    while m > 0 and heights_and_grow_rates and p > k:
        _, prev_h = heapq.heappop(heights_and_grow_rates)
        if prev_h + p > 0:
            heapq.heappush(heights_and_grow_rates, (max(0, prev_h + p - k), prev_h + p))
        else:
            break
        m -= 1

    while m > 0:
        _, prev_h = heapq.heappop(heights_and_grow_rates)
        heapq.heappush(heights_and_grow_rates, (prev_h + k - 1, prev_h + k))
        m -= 1

    prev_h, _ = heapq.heappop(heights_and_grow_rates)
    min_max_height = -(prev_h // -p)
    while max_heights and -max_heights[0] < min_max_height:
        max_heights.pop(0)
    return min(p - (min_max_height * max_heights[0]) % p, k)

