from collections import defaultdict

def BFS(graph, root):
    visited = [False] * len(graph)
    queue = [root]
    visited[root] = True

    while queue:
        node = queue.pop(0)
        if graph[node]:
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    return all(visited)

def can_find_cycle(root, target_char, graph):
    queue = [(root, [])]
    visited = {root: 0}
    while queue:
        node, path = queue.pop(0)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited[neighbor] = 1
                if BFS(graph, neighbor):
                    if path[-1] == target_char:
                        return path
                    else:
                        return BFS(graph, neighbor)

    return False

def solve_graph(n, q, queries):
    graph = defaultdict(list)
    for query in queries:
        operation, u, v, c = query.split()
        c = ord(c) - ord('a')

        if operation == "+":
            graph[u-1].append((v-1, c))
        elif operation == "-":
            index = (u-1, v-1)
            if index in graph[n-1]:
                graph[index][1] = c

    results = []
    for u, v in graph[n-1]:
        result = can_find_cycle(u, v, graph)
        results.append("YES" if result else "NO")

    return results

