    tokens = tokenize_line(source)
    new_tokens = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token in inputs:
            new_token = rename_word(token, inputs)
            new_tokens.append(new_token)
        elif token in reserved_tokens:
            new_tokens.append(token)
        else:
            new_tokens.append(adj_round(token))
        i += 1
    new_tokens = [token for token in new_tokens if token !='']
    return new_tokens

def tokenize_line(line):
    pattern = r'([\s]+|#)(.*?)([\s]+)'
    matches = re.findall(pattern, line)
    tokens = []
    if len(matches) == 2:
        # This line contains comments, whitespace, and tokens
        tokens = matches[1].split()
    else:
        tokens.append(line.strip())
    return tokens

def adj_round(token):
    if len(token) == 1:
        return token
    cycle = 0
    while True:
        cycle += 1
        if token.startswith('..') and not token.endswith('..'):
            token += 'd'
        elif token.endswith('.d'):
            token = token[:-2]
        else:
            break
    if cycle > 1 or token.startswith('d.'):
        token = 'd.' + token
    repeats = 's' + token + 'c'
    return repeats

def rename_word(word, inputs):
    global reserved_tokens
    if len(word) < len(max(reserved_tokens)):
        if word not in reserved_tokens:
            reserved_tokens.append(word)
    new_word = rename(word, inputs)
    return new_word

def rename(word, inputs):
    # Transform 'd'd to 'ds'
    if word.endswith('.d'):
        word = word[:-2]
    new_word = word
    for new, old in inputs:
        if word.startswith(new):
            new_word = old
            break
    return new_word

# Create dictionary to map show tokens to names
inputs = []
for word in reserved_tokens + ['#']:
    inputs.append((word[::-1], word))

print(''.join(minify(sources[0], inputs)).strip())
