from collections import defaultdict

def minimum_broom_size(n):
    # Initialize the broom with vertex representing the root
    broom = [1]

    for i in range(2, n + 1):
        # Get the last vertex last in the broom
        last_vertex = broom[-1]

        # Gather the number of new vertices added
        new_vertices_to_add = [len(neighbors) for _, neighbor in enumerate(broom) for (_, _, letter) in parents[neighbor] if letter == 'a']

        # Flag iterates through the collected new vertices keeping keys sorted
        pursue_flag = False

        for keys in reversed(new_vertices_to_add):
            if keys[0] > broom[-1]:
                follow_flag = False
            else:
                follow_flag = pursue_flag

            # If the new vertex stands out leading all pre-set predecessors, partial palindrome will swallow
            if follow_flag:
                break

            # Check if any words of this size leads to a root node next to outbound leaf edge
            bisect_idx = bisect.bisect_left(new_vertices_to_add, keys)
            for key_next in new_vertices_to_add[bisect_idx:]:
                if broom[key_next - 2] < broom[last_vertex - 1]:
                    follow_flag = True
                    break
                if process_step(broom, (key_next, keys[key_next - 2]), last_vertex, new_vertices_to_add):
                    break
            else:
                return n, n + 1 if follow_flag else n + 1

            broom.append(keys[-1])

    return n + 1, max(broom)

def process_step(broom, edge, parent, new_vertices):
    last_vertex = broom[-1]
    parent_brooms = broom[:parent][::-1]

    for (a, b), a_break in zip(new_vertices, new_vertices[-1] - 1):
        if a_break:
            if a > a + 1:
                parent_brooms[a] = a + 1
                if a > 0:
                    return len(broom)
            else:
                new_vertices[a] = a + 1

    bisect_idx = bisect.bisect_left(new_vertices, parent - 1)
    p_broom = bs_pair(broom, new_vertices[bisect_idx-1], new_vertices[bisect_idx]) 
    for key_next in new_vertices[bisect_idx:]:
        if a > broom[key_next - 2]:
            new_vertices[key_next - 1] = a
            bisect.insort_left(parent_brooms, key_next)
    return len(broom)

def bs_pair(bro, a, b):
    if a in bro: 
        return a, min(bro[a])
    if b in bro: 
        return b, max(bro[b])
    return 0, 1

