from collections import deque

def max_difference(s):
    queue = deque()
    for num in s:
        while queue and queue[-1] < num:
            queue.pop()
        queue.append(num)
    # Calculate the product of elements of the balanced array.
    balance = sum(queue[i] * (len(queue) - i - 1) for i in range(len(s)))
    # Calculate difference of sum pairs of the subarrays.
    max_sum = balance
    for i in range(len(s)):
        while queue and queue[0] < s[i]:
            queue.popleft()
        balance -= queue[0] * i
        balance += s[i] * (len(s) - i - 1)
        max_sum = max(max_sum, balance)
    return max_sum

def main():
    n, k = map(int, input().split())
    s = list(map(int, input().split()))
    return max_difference(s)

if __name__ == '__main__':
    print(main())
